import os

cwd = os.getcwd()
print("CWD:", cwd)
for name in sorted(os.listdir(cwd)):
    full = os.path.join(cwd, name)
    if os.path.isfile(full):
        print(f"FILE {name} ({os.path.getsize(full)} bytes)")
    else:
        print(f"DIR  {name}")

